package com.vaijunto.service;
import com.vaijunto.domain.entities.*; import com.vaijunto.dto.*; import com.vaijunto.exception.ApiException; import com.vaijunto.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class ConversationService { private final ConversationRepository conversations; private final ConversationMessageRepository messages; private final MessageReportRepository reports; private final MediaObjectRepository media; private final UserRepository users; private final NotificationService notifications; private final ReportEvidenceSnapshotRepository evidence; private final RealtimeEventPublisher realtimeEvents;
 @Transactional public List<ConversationDto> list(String email){var u=users.findByEmail(email).orElseThrow(ApiException::userNotFound);return conversations.findForUser(u.getId()).stream().map(c->{if(c.getReadOnlyAt()==null&&c.getRide()!=null&&c.getRide().getActualEnd()!=null&&c.getRide().getActualEnd().plusHours(24).isBefore(OffsetDateTime.now()))c.setReadOnlyAt(c.getRide().getActualEnd().plusHours(24));return ConversationDto.from(c,u.getId());}).toList();}
 @Transactional public List<MessageDto> history(UUID conversationId,String email){var user=user(email);var c=authorized(conversationId,user);var history=messages.findByConversationIdOrderBySentAtAsc(c.getId());for(var message:history)if((message.getSender()==null||!message.getSender().getId().equals(user.getId()))&&message.getReadAt()==null)message.setReadAt(OffsetDateTime.now());return history.stream().map(MessageDto::from).toList();}
 @Transactional public MessageDto send(UUID conversationId, SendMessageRequest request, String email){var user=user(email);var c=authorized(conversationId,user); if(c.getReadOnlyAt()!=null||"OFFICIAL".equals(c.getType()))throw new ApiException(HttpStatus.CONFLICT,"CONVERSATION_READ_ONLY","Esta conversa está somente para leitura."); var existing=messages.findByConversationIdAndClientId(c.getId(),request.clientId()); if(existing.isPresent())return MessageDto.from(existing.get()); String kind=request.kind().trim().toUpperCase(Locale.ROOT); var ids=request.mediaIds()==null?List.<UUID>of():request.mediaIds();if(!Set.of("TEXT","LOCATION").contains(kind))throw new ApiException(HttpStatus.BAD_REQUEST,"MESSAGE_KIND_INVALID","Tipo de mensagem inválido."); if("TEXT".equals(kind)&&(request.body()==null||request.body().isBlank())&&ids.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"MESSAGE_EMPTY","Escreva uma mensagem antes de enviar.");if("LOCATION".equals(kind)&&(request.locationJson()==null||request.locationJson().isBlank()))throw new ApiException(HttpStatus.BAD_REQUEST,"LOCATION_EMPTY","Informe uma localização válida."); ConversationMessage reply=null; if(request.replyToId()!=null){reply=messages.findById(request.replyToId()).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"REPLY_NOT_FOUND","Mensagem de referência não encontrada."));if(!reply.getConversation().getId().equals(c.getId()))throw ApiException.conversationForbidden();} var message=messages.save(ConversationMessage.builder().conversation(c).sender(user).clientId(request.clientId()).kind(kind).body(request.body()==null?null:request.body().trim()).locationJson(request.locationJson()).replyTo(reply).deliveredAt(OffsetDateTime.now()).build());for(var id:ids){var object=media.findByIdAndOwnerId(id,user.getId()).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"MEDIA_NOT_FOUND","Mídia não encontrada."));if(!"ACTIVE".equals(object.getStatus())||object.getConversation()==null||!object.getConversation().getId().equals(c.getId())||object.getMessage()!=null)throw new ApiException(HttpStatus.BAD_REQUEST,"MEDIA_NOT_ATTACHABLE","Mídia indisponível para esta conversa.");object.setMessage(message);} c.setLastActivityAt(OffsetDateTime.now());var other=Objects.equals(c.getParticipantA()==null?null:c.getParticipantA().getId(),user.getId())?c.getParticipantB():c.getParticipantA();if(other!=null)notifications.createAndSendNotification(other.getId(),user.getName(),"Nova mensagem na sua carona.","CHAT_MESSAGE","{\"conversationId\":\""+c.getId()+"\"}",null); return MessageDto.from(message);}
 @Transactional public MessageDto edit(UUID conversationId,UUID messageId,String body,String email){var user=user(email);authorized(conversationId,user);var m=messages.findById(messageId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"MESSAGE_NOT_FOUND","Mensagem não encontrada."));if(!m.getConversation().getId().equals(conversationId)||!m.getSender().getId().equals(user.getId()))throw ApiException.conversationForbidden();if(m.getSentAt().plusMinutes(1).isBefore(OffsetDateTime.now()))throw new ApiException(HttpStatus.CONFLICT,"EDIT_WINDOW_EXPIRED","Mensagens só podem ser editadas por um minuto.");if(!"TEXT".equals(m.getKind())||m.getDeletedAt()!=null||body==null||body.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"MESSAGE_NOT_EDITABLE","Esta mensagem não pode ser editada.");m.setBody(body.trim());m.setEditedAt(OffsetDateTime.now());publish(m.getConversation(),"MESSAGE_UPDATED",m.getId());return MessageDto.from(m);}
 @Transactional public void delete(UUID conversationId,UUID messageId,String email){var user=user(email);var c=authorized(conversationId,user);var m=messages.findById(messageId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"MESSAGE_NOT_FOUND","Mensagem não encontrada."));if("ADMINISTRATIVE".equals(c.getType()))throw new ApiException(HttpStatus.CONFLICT,"ADMIN_MESSAGE_PERMANENT","Mensagens administrativas são permanentes.");if(!m.getConversation().getId().equals(conversationId)||m.getSender()==null||!m.getSender().getId().equals(user.getId()))throw ApiException.conversationForbidden();if(m.getSentAt().plusMinutes(1).isBefore(OffsetDateTime.now()))throw new ApiException(HttpStatus.CONFLICT,"DELETE_WINDOW_EXPIRED","Mensagens só podem ser apagadas por um minuto.");m.setDeletedAt(OffsetDateTime.now());publish(c,"MESSAGE_DELETED",m.getId());}
 @Transactional public UUID report(UUID conversationId,ReportMessagesRequest request,String email){var user=user(email);var c=authorized(conversationId,user);Set<ConversationMessage> selected=new LinkedHashSet<>(); for(UUID messageId:request.messageIds()){var m=messages.findById(messageId).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"MESSAGE_NOT_FOUND","Uma mensagem selecionada não foi encontrada."));if(!m.getConversation().getId().equals(conversationId))throw ApiException.conversationForbidden();for(var attachment:m.getMedia()){attachment.setCategory("REPORT");attachment.setDeleteAfter(null);}selected.add(m);}var report=reports.save(MessageReport.builder().reporter(user).conversation(c).messages(selected).build());for(var m:selected)evidence.save(ReportEvidenceSnapshot.builder().report(report).originalMessageId(m.getId()).senderId(m.getSender().getId()).kind(m.getKind()).body(m.getBody()).locationJson(m.getLocationJson()).sentAt(m.getSentAt()).mediaIdsJson(m.getMedia().stream().map(x->"\""+x.getId()+"\"").collect(java.util.stream.Collectors.joining(",","[","]"))).createdAt(OffsetDateTime.now()).build());return report.getId();}
 @Transactional public void officialAction(UUID conversationId,String action,String email){var user=user(email);var conversation=authorized(conversationId,user);if(!"OFFICIAL".equals(conversation.getType()))throw new ApiException(HttpStatus.BAD_REQUEST,"OFFICIAL_ACTION_INVALID","Ação disponível apenas no canal oficial.");String normalized=action.trim().toUpperCase(Locale.ROOT);if(!Set.of("JUSTIFICAR","VER_CARONA","AINDA_NAO_CHEGUEI").contains(normalized))throw new ApiException(HttpStatus.BAD_REQUEST,"OFFICIAL_ACTION_INVALID","Ação oficial inválida.");String body=switch(normalized){case "JUSTIFICAR"->"Recebemos seu pedido de justificativa. Acompanhe as próximas orientações.";case "VER_CARONA"->"Abrindo os dados da sua carona.";default->"Registramos que você ainda não chegou. Vamos acompanhar sua carona.";};notifications.createAndSendNotification(user.getId(),"VaiJunto",body,"OFFICIAL_ACTION","{\"action\":\""+normalized+"\"}",null);}
 private void publish(Conversation c,String type,UUID messageId){var recipients=new ArrayList<String>();if(c.getParticipantA()!=null)recipients.add(c.getParticipantA().getEmail());if(c.getParticipantB()!=null)recipients.add(c.getParticipantB().getEmail());realtimeEvents.afterCommit(recipients,RealtimeEventDto.create(type,"MESSAGE",messageId,Map.of("conversationId",c.getId().toString(),"messageId",messageId.toString())));}
 private User user(String email){return users.findByEmail(email).orElseThrow(ApiException::userNotFound);}
 public String otherParticipantEmail(UUID conversationId,String email){var current=user(email);var c=authorized(conversationId,current);var other=Objects.equals(c.getParticipantA()==null?null:c.getParticipantA().getId(),current.getId())?c.getParticipantB():c.getParticipantA();if(other==null)throw ApiException.conversationForbidden();return other.getEmail();}
 private Conversation authorized(UUID id,User user){var c=conversations.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"CONVERSATION_NOT_FOUND","Conversa não encontrada."));if(!Objects.equals(c.getParticipantA()==null?null:c.getParticipantA().getId(),user.getId())&&!Objects.equals(c.getParticipantB()==null?null:c.getParticipantB().getId(),user.getId()))throw ApiException.conversationForbidden();return c;}
}
